{"type":"fact","doc_id":"d1_10-34-numerical-methods-applied-to-chemi_syllabus","statement":"10.34 lectures meet 3 sessions per week, 1 hour per session.","source_span":"Lectures: 3 sessions / week, 1 hour / session"}
